export class VoidReasonsPanel {
  protected readonly reasons = inject(VoidReasons);
  private readonly sheets = inject(Sheets);

  protected readonly error = signal<string | null>(null);
  protected readonly saving = signal(false);
  protected readonly form = new FormGroup({
    reason: new FormControl('', { nonNullable: true }),
  });

  constructor() {
    // Each (re)load of a sheet re-reads its void reasons from the store.
    toObservable(this.sheets.loaded)
      .pipe(
        switchMap((sheet) => {
          this.error.set(null);
          return this.reasons.load(sheet?.id ?? null) ?? EMPTY;
        }),
        takeUntilDestroyed(),
      )
      .subscribe({ error: () => this.error.set('Could not read the void reasons.') });
    // An error is removed as soon as its form is changed.
    this.form.valueChanges.pipe(takeUntilDestroyed()).subscribe(() => this.error.set(null));
  }

  protected add(): void {
    // A second submit before the first has answered is ignored, so it stores one reason.
    if (this.saving()) return;
    this.error.set(null);
    const sheet = this.sheets.current();
    if (!sheet) return;
    const reason = this.form.controls.reason.value.trim().replace(/\s+/g, ' ');
    if (reason === '') {
      this.error.set('Type the void reason.');
      return;
    }
    if (this.reasons.all().some((r) => r.reason === reason)) {
      this.error.set('That reason is already on the list.');
      return;
    }
    this.saving.set(true);
    this.reasons.add(sheet.id, reason).subscribe({
      next: () => {
        this.saving.set(false);
        this.form.reset({ reason: '' }, { emitEvent: false });
      },
      error: () => {
        this.saving.set(false);
        this.error.set('Could not add the void reason: it may already be on the list.');
      },
    });
  }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject, signal } from '@angular/core';
import { Observable, tap } from 'rxjs';

/** A void reason on the sheet: while the list is not empty, a claim is voided with one of them. */
export interface VoidReasonView {
  id: number;
  reason: string;
}

// The void reasons on the active sheet, in the order they were added.
@Injectable({ providedIn: 'root' })
export class VoidReasons {
  private readonly http = inject(HttpClient);
  private readonly list = signal<VoidReasonView[]>([]);
  readonly all = this.list.asReadonly();

  /** Re-read a sheet's void reasons from the store; null clears them. */
  load(sheetId: string | null): Observable<VoidReasonView[]> | null {
    this.list.set([]);
    if (sheetId === null) return null;
    return this.http.get<VoidReasonView[]>(this.base(sheetId)).pipe(tap((list) => this.list.set(list)));
  }

  /** Add a void reason; refused when blank or already on the list. */
  add(sheetId: string, reason: string): Observable<VoidReasonView> {
    return this.http.post<VoidReasonView>(this.base(sheetId), { reason }).pipe(
      tap((saved) => this.list.update((list) => [...list, saved])),
    );
  }

  private base(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}/void-reasons`;
  }
}
-- The void reasons on a sheet: while its list is not empty, a claim is voided with one of them. Each reason is on a
-- sheet's list at most once. Ids rise in the order reasons were added.
CREATE TABLE void_reason (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    reason   VARCHAR(200) NOT NULL
);
CREATE UNIQUE INDEX void_reason_sheet_reason ON void_reason (sheet_id, reason);

-- The reason from its sheet's list a claim was voided with; none when it is not void or was voided without one.
ALTER TABLE claim ADD COLUMN void_reason VARCHAR(200);
