const NO_RATES: readonly RateView[] = [];

// One person's claims: their claimed total, one form to add a claim or edit an existing one, and
// the claims listed newest first.
/** Why a claim above the proof threshold is refused a settle or approval. */
/** The permission matrix action a move to each status is. */
const STATUS_ACTION: Partial<Record<ClaimStatus, string>> = { OPEN: 'open', SETTLED: 'settle', VOID: 'void' };
const UNNOTED = 'This claim\'s due is above the note threshold, so it needs a note before it can be opened.';
const UNPROVEN = 'This claim\'s due is above the proof threshold, so it needs a proof first.';

@Component({
  selector: 'app-person-claims',
  imports: [ReactiveFormsModule],
  template: `
    <p>Claimed: <span data-testid="person-claimed">{{ claimed() }}</span></p>

    <form [formGroup]="form" (ngSubmit)="submit()"
          [attr.aria-label]="(editingId() === null ? 'Add a claim for ' : 'Edit a claim of ') + personName()">
      <label [for]="fieldId('amount')">Amount</label>
      <input [id]="fieldId('amount')" data-testid="claim-form-amount" formControlName="amount"
             inputmode="decimal" autocomplete="off" />
      <label [for]="fieldId('date')">Date</label>
      <input [id]="fieldId('date')" type="date" data-testid="claim-form-date" formControlName="date" />
      <label [for]="fieldId('note')">Note</label>
      <input [id]="fieldId('note')" data-testid="claim-form-note" formControlName="note" autocomplete="off" />
      <label [for]="fieldId('corrects')">Corrects claim No.</label>
      <input [id]="fieldId('corrects')" data-testid="claim-form-corrects" formControlName="corrects"
             inputmode="numeric" autocomplete="off" />
      <label [for]="fieldId('ref')">Reference</label>
      <input [id]="fieldId('ref')" data-testid="claim-form-ref" formControlName="ref" autocomplete="off" />
      <label [for]="fieldId('tags')">Tags (comma separated)</label>
      <input [id]="fieldId('tags')" data-testid="claim-form-tags" formControlName="tags" autocomplete="off" />
      <button type="submit" data-testid="claim-form-submit" [disabled]="saving()">
        {{ editingId() === null ? 'Add claim' : 'Save claim' }}
      </button>
      @if (error(); as err) {
        <p role="alert" data-testid="claim-form-error">{{ err }}</p>
      }
    </form>

    <ul [attr.aria-label]="'Claims of ' + personName()">
      @for (c of claims(); track c.id) {
        <li [attr.data-testid]="'claim-row-' + c.id">
          <input type="checkbox" data-testid="claim-select" [checked]="selected().has(c.id)"
                 (change)="selectToggled.emit({ id: c.id, selected: $any($event.target).checked })"
                 [attr.aria-label]="'Select claim of ' + c.amount + ' on ' + c.date" />
          No. <span data-testid="claim-number">{{ c.number ?? '' }}</span>
          <span data-testid="claim-amount">{{ c.amount }}</span>
}

// The claims people on a sheet have made, listed newest first.
@Injectable({ providedIn: 'root' })
export class Claims {
  private readonly http = inject(HttpClient);

  list(sheetId: string): Observable<ClaimView[]> {
    return this.http.get<ClaimView[]>(`${this.base(sheetId)}/claims`);
  }

  add(sheetId: string, personId: number, claim: ClaimForm): Observable<ClaimView> {
    return this.http.post<ClaimView>(`${this.base(sheetId)}/people/${personId}/claims`, claim);
  }

  /** Add a DRAFT claim for the person named `name`, dated the sheet's today; one not on the sheet is
   *  added first with grade A. Refused as a whole when the person or the claim is. */
  quickAdd(sheetId: string, name: string, amount: string): Observable<QuickAddView> {
    return this.http.post<QuickAddView>(`${this.base(sheetId)}/quick-add`, { name, amount });
  }

  /** Add a DRAFT claim per line of name,amount,date,note, in order, for people already on the sheet; a note
   *  ending in " #<reference>" gives the claim that reference. Refused as a whole when any line is. */
  paste(sheetId: string, text: string): Observable<PasteView> {
    return this.http.post<PasteView>(`${this.base(sheetId)}/claims/paste`, { text });
  }
import { Component, inject, signal } from '@angular/core';
import { FormControl, FormGroup, ReactiveFormsModule, Validators } from '@angular/forms';
import { Session } from '../../core/session';
import { Sheets } from '../../core/sheet';
import { AuditPanel } from '../audit/audit';
import { DelegationsPanel } from '../delegations/delegations';
import { HolidaysPanel } from '../holidays/holidays';
import { PeopleList } from '../people/people';
import { RatesPanel } from '../rates/rates';
import { SettingsPanel } from '../settings/settings';
import { VoidReasonsPanel } from '../void-reasons/void-reasons';

// The one screen: sign in by name, then choose a sheet by id. Everything else is per sheet.
@Component({
  selector: 'app-home',
  imports: [ReactiveFormsModule, PeopleList, RatesPanel, SettingsPanel, DelegationsPanel, HolidaysPanel,
    VoidReasonsPanel, AuditPanel],
  template: `
    @if (session.user(); as user) {
      <p>Signed in as <strong data-testid="current-user">{{ user }}</strong></p>

      <form [formGroup]="sheetForm" (ngSubmit)="loadSheet()" aria-label="Load a sheet">
        <label for="sheet-id">Sheet id</label>
        <input id="sheet-id" data-testid="sheet-id-input" formControlName="id" autocomplete="off" />
        <button type="submit" data-testid="sheet-load" [disabled]="loading()">Load</button>
        @if (sheetError(); as err) {
          <p role="alert" data-testid="sheet-load-error">{{ err }}</p>
        }
      </form>

      @if (sheets.current(); as sheet) {
        <p>Sheet: <strong data-testid="sheet-current-id">{{ sheet.id }}</strong></p>
        <p>Today: <strong data-testid="sheet-today">{{ sheet.today }}</strong></p>
        <p>
          Archived: <strong data-testid="sheet-archived">{{ sheet.archived ? 'yes' : 'no' }}</strong>
          <button type="button" data-testid="sheet-archive" [disabled]="archiving()" (click)="archive()">Archive sheet</button>
        </p>

        <form [formGroup]="asOfForm" (ngSubmit)="setAsOf()" aria-label="Show the sheet as of a date">
          <p>As of: <strong data-testid="sheet-asof">{{ sheet.asOf ?? '' }}</strong></p>
          <label for="asof-date">Show as of</label>
          <input id="asof-date" type="date" data-testid="asof-date" formControlName="date" />
          <button type="submit" data-testid="asof-set" [disabled]="settingAsOf()">Set as of</button>
          <button type="button" data-testid="asof-clear" [disabled]="settingAsOf()" (click)="clearAsOf()">Clear as of</button>
          @if (asOfError(); as err) {
            <p role="alert" data-testid="asof-error">{{ err }}</p>
          }
        </form>

        <form [formGroup]="todayForm" (ngSubmit)="saveToday()" aria-label="Change the sheet's today">
          <label for="sheet-today-input">Change today</label>
          <input id="sheet-today-input" type="date" data-testid="sheet-today-input" formControlName="today" />
          <button type="submit" data-testid="sheet-today-save" [disabled]="savingToday()">Set today</button>
          @if (todayError(); as err) {
            <p role="alert" data-testid="sheet-error">{{ err }}</p>
          }
        </form>

        <app-rates />
        <app-settings />
        <app-delegations />
        <app-holidays />
        <app-void-reasons />
        <app-people />
        <app-audit />
      } @else {
        <p data-testid="sheet-none">Load a sheet to begin.</p>
      }
    } @else {
      <form [formGroup]="signInForm" (ngSubmit)="signIn()" aria-label="Sign in">
        <label for="signin-name">Your name</label>
        <input id="signin-name" data-testid="signin-name" formControlName="name" autocomplete="username" />
        <button type="submit" data-testid="signin-submit">Sign in</button>
        @if (signInError(); as err) {
          <p role="alert" data-testid="signin-error">{{ err }}</p>
        }
      </form>
    }
  `,
})

