      return;
    }
    this.saving.set(true);
    this.templates.addClaim(sheet.id, this.personId(), name).subscribe({
      next: (saved) => {
        this.saving.set(false);
        this.saved.emit(saved);
      },
      error: (err: unknown) => {
        this.saving.set(false);
        this.error.set(
